-- Guarded cleanup of inert legacy resource child pools, batch 10.
-- Physical gameobject rows are untouched.
START TRANSACTION;
DELETE pp FROM pool_pool pp LEFT JOIN pool_creature pc ON pc.pool_entry=pp.pool_id LEFT JOIN pool_gameobject pg ON pg.pool_entry=pp.pool_id LEFT JOIN pool_quest pq ON pq.pool_entry=pp.pool_id LEFT JOIN game_event_pool gep ON gep.pool_entry=pp.pool_id LEFT JOIN pool_pool child ON child.mother_pool=pp.pool_id WHERE pp.pool_id IN (2416,2417,2418,2419,2420,2421,2422,2423,2424,2425,2426,2427,2428,2429,2430,2433,2434,2435,2436,2437,2438,2440,2441,2442,2443,2444,2446,2447,2450,2451,2452,2453,2456,2457,2459,2461,2463,2464,2465,2467,2468,2469,2470,2471,2472,2473,2474,2475,2476,2477) AND pc.guid IS NULL AND pg.guid IS NULL AND pq.entry IS NULL AND gep.pool_entry IS NULL AND child.pool_id IS NULL;
DELETE pt FROM pool_template pt LEFT JOIN pool_creature pc ON pc.pool_entry=pt.entry LEFT JOIN pool_gameobject pg ON pg.pool_entry=pt.entry LEFT JOIN pool_quest pq ON pq.pool_entry=pt.entry LEFT JOIN game_event_pool gep ON gep.pool_entry=pt.entry LEFT JOIN pool_pool pp_child ON pp_child.pool_id=pt.entry LEFT JOIN pool_pool pp_mother ON pp_mother.mother_pool=pt.entry WHERE pt.entry IN (2416,2417,2418,2419,2420,2421,2422,2423,2424,2425,2426,2427,2428,2429,2430,2433,2434,2435,2436,2437,2438,2440,2441,2442,2443,2444,2446,2447,2450,2451,2452,2453,2456,2457,2459,2461,2463,2464,2465,2467,2468,2469,2470,2471,2472,2473,2474,2475,2476,2477) AND pc.guid IS NULL AND pg.guid IS NULL AND pq.entry IS NULL AND gep.pool_entry IS NULL AND pp_child.pool_id IS NULL AND pp_mother.pool_id IS NULL;
COMMIT;

